Validation failed for tool "set_answer_spec":
  - root: must not have additional properties

Received arguments:
{
  "taskId": "task_151d9d28-b1a3-4e01-902e-da55596e96d6",
  "fields": {
    "population.entity": {
      "value": {
        "name": "每日玩具销售额（日历日 × brinquedos 类目销售额合计）",
        "keyColumns": [
          "销售日期"
        ]
      },
      "basis": "assumed",
      "rationale": "题面未指定实体键；以'每日'为粒度，按 order_purchase_timestamp 的日期聚合玩具类目销售额",
      "evidenceIds": [
        "evidence_0d3054ee-e709-41f3-aad3-a353c14659a3"
      ]
    },
    "population.eligibility": {
      "value": "2017-01-01 至 2018-08-29 的全部 606 个日历日均纳入；无玩具销售的日期计入该日序列（值 0）",
      "basis": "assumed",
      "rationale": "线性回归需要连续的日序列；观测显示玩具类目销售非常稀疏（窗口内仅 ~300 天有销售），若不补零则序列不连续。无更权威依据，属未证实假设",
      "evidenceIds": [
        "evidence_88bfccd4-f1f9-4461-bbf3-cf12c47965f2"
      ]
    },
    "population.conditions": {
      "value": [
        "products.product_category_name = 'brinquedos'（英文名 toys），不限订单状态"
      ],
      "evidenceIds": [
        "evidence_388de247-b841-47f6-b38b-83210fc0c931"
      ]
    },
    "population.source": {
      "value": {
        "tables": [
          "orders",
          "order_items",
          "products"
        ]
      },
      "evidenceIds": [
        "evidence_72da646c-7ee4-4e26-884b-dbe2e40182df"
      ]
    },
    "population.joinMultiplicity": {
      "value": "orders : order_items = 1:N（按 order_id 连接，一单多件会复制行），聚合到日期求和前先按日汇总；products 按 product_id 与 order_items 为 1:1，不复制度量",
      "basis": "assumed",
      "rationale": "按 order_id/product_id 连接的基数按 Olist 结构判定"
    }
  },
  "population.timeField": {
    "value": "orders.order_purchase_timestamp（下单时间，取日期部分）",
    "evidenceIds": [
      "evidence_39cf69a2-0b4b-437b-9501-3dad3777acaf"
    ]
  },
  "population.missing": {
    "value": "缺期（无销售日）按 0 补齐，按相邻日历日而非相邻观测计算回归的自变量",
    "basis": "assumed",
    "rationale": "同上；回归自变量按日历日连续编号"
  },
  "measure.formula": {
    "value": {
      "op": "custom",
      "description": "对 2017-01-01..2018-08-29 的每日玩具销售额（brinquedos 类目 oi.price 按日合计，缺日补 0）拟合简单线性回归 sales = a + b·x（x = 自 2017-01-01 起的日历日序号）；据此预测 2018-12-05..2018-12-08 的日销售额 P(x)；对每个预测日取 5 日对称（中心）移动平均 MA(x) = (P(x-2)+P(x-1)+P(x)+P(x+1)+P(x+2))/5；最后对 12-05..12-08 这 4 个 MA 求和",
      "of": "daily toy sales"
    },
    "basis": "request",
    "quote": "5-day symmetric moving average of predicted toy sales"
  },
  "output": {
    "value": {
      "rowMode": "scalar",
      "columns": [
        "total_sum_of_moving_averages"
      ],
      "units": {
        "total_sum_of_moving_averages": "BRL(订单商品金额合计)"
      },
      "decimals": {
        "total_sum_of_moving_averages": 2
      }
    }
  },
  "population.time": {
    "value": "2017-01-01 至 2018-08-29（含端点，606 个日历日）",
    "basis": "request",
    "quote": "from January 1, 2017, to August 29, 2018"
  }
}
